/** `just serve`. The dev servers alone, against an instance that is already up. */

import { spawnResolved } from './command.mjs';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { resolveDevServerPorts } from './ports.mjs';
import {
  anyExited,
  awaitDevServersReady,
  finishDevServers,
  INTERRUPTED,
  notAnswering,
  startDevServers,
  stoppedMessage,
  superviseStartup,
} from './devservers.mjs';
import { urlTable } from './report.mjs';
import { envFileFor, readProxyPort, stateDirFor } from './compose.mjs';
import { currentInstanceHere, runEntryPoint } from './entrypoint.mjs';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

export async function main(argv) {
  const instance = currentInstanceHere(REPO_ROOT);

  const stateDir = stateDirFor(instance);
  if (!existsSync(envFileFor(instance))) {
    console.error(`No rendered environment at ${stateDir}. Run \`just up\` first.`);
    return 1;
  } else {
    const proxyPort = readProxyPort(instance);
    const selection = argv.find((arg) => arg.startsWith('--apps='));
    const apps = selection ? selection.slice('--apps='.length) : null;
    const ports = await resolveDevServerPorts(stateDir);
    const handle = await startDevServers({
      repoRoot: REPO_ROOT,
      instance,
      ports,
      selection: apps,
      spawnProcess: spawnResolved,
    });

    // Same reason as `just up`: the table is only true once the dev servers can answer. And the
    // same supervision: a Ctrl-C while they are still building stops them rather than leaving them.
    const outcome = await superviseStartup(handle, () => awaitDevServersReady({ handle }));

    if (outcome === INTERRUPTED) {
      console.log(stoppedMessage());
      return 130;
    } else {
      if (anyExited(outcome)) {
        // Its crash report is already on screen; `finishDevServers` turns it into the exit code.
      } else {
        console.log(`\n${urlTable(instance, proxyPort, notAnswering(outcome))}\n`);
      }
      // The exact failure the crash race exists to eliminate: without it, one dev server dying on
      // its own left `just serve` sitting there looking healthy. `finishDevServers` races the crash
      // against the stop signals and reports whichever one actually happened.
      const exitCode = await finishDevServers({ handle });
      console.log(stoppedMessage());
      return exitCode;
    }
  }
}

await runEntryPoint(import.meta.url, main);
